#!/usr/bin/env python3
from pathlib import Path

root = Path(__file__).resolve().parents[2]

# Expose the aggregate scalar-slot cardinality already owned by ast_global.c so
# parser-side backward overlays use the same canonical flattening contract as
# relocation verification and record-field slot lookup.
h = root / "src/frontend/ast.h"
text = h.read_text()
old_h = '''bool minic_c0_global_record_field_initializer_slot(const MinicC0Program *program,\n                                                   const MinicRecord *record,\n                                                   size_t field_index,\n                                                   size_t *slot_index);\n'''
new_h = '''bool minic_c0_global_initializer_slot_count(const MinicC0Program *program,\n                                            MinicType type,\n                                            size_t *slot_count);\nbool minic_c0_global_record_field_initializer_slot(const MinicC0Program *program,\n                                                   const MinicRecord *record,\n                                                   size_t field_index,\n                                                   size_t *slot_index);\n'''
if text.count(old_h) != 1:
    raise SystemExit(f"ast.h slot helper anchor count={text.count(old_h)}")
h.write_text(text.replace(old_h, new_h, 1))

c = root / "src/frontend/ast_global.c"
text = c.read_text()
old_c = '''bool minic_c0_global_record_field_initializer_slot(const MinicC0Program *program,\n                                                   const MinicRecord *record,\n                                                   size_t field_index,\n                                                   size_t *slot_index) {\n'''
new_c = '''bool minic_c0_global_initializer_slot_count(const MinicC0Program *program,\n                                            MinicType type,\n                                            size_t *slot_count) {\n    return aggregate_scalar_slot_count(program, type, slot_count);\n}\n\nbool minic_c0_global_record_field_initializer_slot(const MinicC0Program *program,\n                                                   const MinicRecord *record,\n                                                   size_t field_index,\n                                                   size_t *slot_index) {\n'''
if text.count(old_c) != 1:
    raise SystemExit(f"ast_global.c slot helper anchor count={text.count(old_c)}")
c.write_text(text.replace(old_c, new_c, 1))

p = root / "src/frontend/parser_global.c"
text = p.read_text()

old_decl = '''static bool overwrite_static_zero_record_value(MinicParser *parser,\n                                               MinicGlobalObjectId object_id,\n                                               MinicType type,\n                                               const MinicRecord *record,\n                                               size_t record_base_slot);\n\nstatic bool overwrite_static_zero_field_value(MinicParser *parser,\n'''
new_decl = '''static bool overwrite_static_zero_record_value(MinicParser *parser,\n                                               MinicGlobalObjectId object_id,\n                                               MinicType type,\n                                               const MinicRecord *record,\n                                               size_t record_base_slot);\n\nstatic bool overwrite_static_zero_array_constant(MinicParser *parser,\n                                                 MinicGlobalObjectId object_id,\n                                                 MinicType element_type,\n                                                 size_t element_count,\n                                                 size_t array_base_slot);\n\nstatic bool overwrite_static_zero_field_value(MinicParser *parser,\n'''

old_tail = '''    if (field->is_array && minic_type_is_char_integer(field->type) &&\n        parser->current.kind == MINIC_TOKEN_STRING_LITERAL) {\n        return minic_parser_replace_zero_bounded_string_literal_initializer(\n            parser, object_id, field_base_slot, field->element_count);\n    }\n    minic_parser_error(parser,\n                       "backward aggregate designator currently requires scalar, record, or "\n                       "character-array zero subobjects");\n    return false;\n}\n\nstatic bool overwrite_static_zero_record_value(MinicParser *parser,\n'''
new_tail = '''    if (field->is_array && minic_type_is_char_integer(field->type) &&\n        parser->current.kind == MINIC_TOKEN_STRING_LITERAL) {\n        return minic_parser_replace_zero_bounded_string_literal_initializer(\n            parser, object_id, field_base_slot, field->element_count);\n    }\n    if (field->is_array) {\n        return overwrite_static_zero_array_constant(\n            parser, object_id, field->type, field->element_count, field_base_slot);\n    }\n    minic_parser_error(parser,\n                       "backward aggregate designator requires a supported zero subobject");\n    return false;\n}\n\nstatic bool overwrite_static_zero_array_element(MinicParser *parser,\n                                                MinicGlobalObjectId object_id,\n                                                MinicType element_type,\n                                                size_t element_base_slot) {\n    if (minic_type_is_integer(element_type) || minic_type_is_pointer(element_type)) {\n        return parse_static_scalar_constant_at(\n            parser, object_id, element_type, true, element_base_slot);\n    }\n    if (minic_type_is_record(element_type)) {\n        const MinicRecord *record;\n\n        record = minic_c0_program_record(parser->program, element_type.record_id);\n        return record != NULL && overwrite_static_zero_record_value(\n                                     parser, object_id, element_type, record, element_base_slot);\n    }\n    if (minic_type_is_array(element_type)) {\n        const MinicArrayType *array_type;\n\n        array_type = minic_c0_program_array_type(parser->program, element_type.array_type_id);\n        return array_type != NULL && array_type->element_count != 0U &&\n               overwrite_static_zero_array_constant(parser,\n                                                    object_id,\n                                                    array_type->element_type,\n                                                    array_type->element_count,\n                                                    element_base_slot);\n    }\n    minic_parser_error(parser, "unsupported backward static array element type");\n    return false;\n}\n\nstatic bool overwrite_static_zero_array_constant(MinicParser *parser,\n                                                 MinicGlobalObjectId object_id,\n                                                 MinicType element_type,\n                                                 size_t element_count,\n                                                 size_t array_base_slot) {\n    size_t element_slots;\n    size_t next_index;\n\n    if (parser == NULL || element_count == 0U ||\n        !minic_c0_global_initializer_slot_count(\n            parser->program, element_type, &element_slots) ||\n        parser->current.kind != MINIC_TOKEN_LBRACE || !minic_parser_advance(parser)) {\n        return false;\n    }\n    next_index = 0U;\n    while (parser->current.kind != MINIC_TOKEN_RBRACE) {\n        size_t first;\n        size_t last;\n        size_t element_base_slot;\n\n        if (parser->current.kind == MINIC_TOKEN_LBRACKET) {\n            if (!minic_parser_parse_array_designator(\n                    parser, element_count, false, &first, &last)) {\n                return false;\n            }\n            if (first != last) {\n                minic_parser_error(\n                    parser, "GNU range designators in backward static arrays are not supported yet");\n                return false;\n            }\n        } else {\n            first = next_index;\n            last = first;\n        }\n        if (first >= element_count ||\n            (element_slots != 0U && first > (SIZE_MAX - array_base_slot) / element_slots)) {\n            minic_parser_error(parser, "backward static array initializer index is out of range");\n            return false;\n        }\n        element_base_slot = array_base_slot + first * element_slots;\n        if (!overwrite_static_zero_array_element(\n                parser, object_id, element_type, element_base_slot)) {\n            return false;\n        }\n        next_index = first + 1U;\n        if (parser->current.kind == MINIC_TOKEN_COMMA) {\n            if (!minic_parser_advance(parser)) {\n                return false;\n            }\n            if (parser->current.kind == MINIC_TOKEN_RBRACE) {\n                break;\n            }\n        } else if (parser->current.kind != MINIC_TOKEN_RBRACE) {\n            minic_parser_error(parser, "expected ',' or '}' in backward static array initializer");\n            return false;\n        }\n    }\n    return minic_parser_expect(\n        parser, MINIC_TOKEN_RBRACE, "expected '}' after backward static array initializer");\n}\n\nstatic bool overwrite_static_zero_record_value(MinicParser *parser,\n'''

for old, new, label in [
    (old_decl, new_decl, "array helper declaration"),
    (old_tail, new_tail, "array overwrite insertion"),
]:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label} anchor count={count}")
    text = text.replace(old, new, 1)

p.write_text(text)
